fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs >= 1_000_000_000L) {
        val seconds = exposureTimeNs / 1_000_000_000L
        if (seconds % 60 == 0) {
            return "${seconds}s"
        }
        return "${1.0 * exposureTimeNs / 1_000_000_000.0}s"
    }
    if (exposureTimeNs >= 1_000_000L) {
        val d = 1_000_000_000.0 / exposureTimeNs
        if (d == d.roundToInt()) {
            return "1/${d.roundToInt()}s"
        }
        return "1/${d.roundToInt(0)}s"
    }
    if (exposureTimeNs >= 100_000L) {
        val d = 1_000_000_000.0 / exposureTimeNs
        if (d >= 1.0 && d.roundToInt() == d.toInt()) {
            return "1/${d.roundToInt()}s"
        }
        return "${d.toStringAsFixed(1)}s"
    }
    if (exposureTimeNs >= 10_000L) {
        val d = 1_000_000_000.0 / exposureTimeNs
        return "1/${d.roundToInt()}s"
    }
    if (exposureTimeNs >= 1_000L) {
        val d = 1_000_000_000.0 / exposureTimeNs
        if (d >= 30.0 && d.roundToInt() == d.toInt()) {
            return "1/${d.roundToInt()}s"
        }
        return "${d.toStringAsFixed(1)}s"
    }
    val d = 1_000_000_000.0 / exposureTimeNs
    return "${d.toStringAsFixed(3)}s"
}

