                        if _is_piece(target) and _is_white(target) != _is_white(piece):
                            promot = (side == 'w' and nr == 7) or (side == 'b' and nr == 0)
                            move_suffix = 'q' if promot else ''
                            moves.append(f"{_algebraic(r, c)}{_algebraic(nr, nc)}{move_suffix}")

            elif ptype == 'N':
                for dr, dc in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
                    nr, nc = r + dr, c + dc
                    if _is_on_board(nr, nc):
