                            if not _is_piece(target) or _is_white(target) != _is_white(piece):
                                moves.append(f"{_algebraic(r, c)}{_algebraic(nr, nc)}")

    # Return all pseudo-legal moves (prompt says don't worry about check legality)
    return moves


def _make_move(board, move: str):
    """Apply a move to the board. Returns new board (doesn't mutate original).
    Move format: UCI like 'e2e4' or 'e7e8q'."""
    if len(move) == 4:
        from_sq = move[:2]
        to_sq = move[2:]
        promo = None
    elif len(move) == 5:
        from_sq = move[:2]
        to_sq = move[2:4]
        promo = move[4]
    else:
        return board

    from_file = ord(from_sq[0]) - ord('a')
    from_rank = int(from_sq[1]) - 1
    to_file = ord(to_sq[0]) - ord('a')
    to_rank = int(to_sq[1]) - 1

    new_board = [row[:] for row in board]
    piece = new_board[from_rank][from_file]
    new_board[to_rank][to_file] = piece
    new_board[from_rank][from_file] = '--'

    # Pawn promotion
    if piece == 'wP' and to_rank == 7:
        new_board[to_rank][to_file] = promo if promo else 'wQ'
    elif piece == 'bP' and to_rank == 0:
        new_board[to_rank][to_file] = promo if promo else 'bQ'

    return new_board


def _board_to_fen(board, side):
    """Convert board to FEN string (simplified, no castling/ep)."""
    board_str = ''
    for r in range(7, -1, -1):
        empty = 0
        for c in range(8):
            if board[r][c] == '--':
                empty += 1
            else:
                if empty > 0:
                    board_str += str(empty)
                    empty = 0
                board_str += board[r][c]
        if empty > 0:
            board_str += str(empty)
        if r > 0:
            board_str += '/'

    return f"{board_str} {side} - 0 1"


def perft(fen: str, depth: int) -> int:
    """Perft: return number of leaf nodes at given depth.
    perft(0) == 1. Counts pseudo-legal moves at each node.
    """

    if depth == 0:
        return 1

    board, side, _, _, _, _, _, _, _, _ = _parse_fen(fen)
    moves = legal_moves(fen)

    if not moves:
        return 1

    total = 0
    for move in moves:
        new_board = _make_move(board, move)
        new_side = 'b' if side == 'w' else 'w'
        new_fen = _board_to_fen(new_board, new_side)
        total += perft(new_fen, depth - 1)

    return total

