# minimal chess move generator - pure Python, stdlib only

PIECE_CHARS = 'PNBRQKpnbrqk'


def _parse_fen(fen: str):
    parts = fen.split()
    board_str = parts[0]
    side = parts[1]
    castling = parts[2]
    ep_sq = parts[3]
    halfmove = int(parts[4])
    fullmove = int(parts[5])

    board = [['--' for _ in range(8)] for _ in range(8)]
    r = 7
    c = 0
    for ch in board_str:
        if ch == '/':
            r -= 1
            c = 0
        elif ch.isdigit():
            c += int(ch)
        else:
            board[r][c] = ch
            c += 1

    ep_file, ep_rank = -1, -1
    if ep_sq != '-':
        ep_file = ord(ep_sq[0]) - ord('a')
        ep_rank = 8 - int(ep_sq[1])

    castle_kingside_w = 'K' in castling
    castle_queenside_w = 'Q' in castling
    castle_kingside_b = 'k' in castling
    castle_queenside_b = 'q' in castling

    return board, side, castle_kingside_w, castle_queenside_w, castle_kingside_b, castle_queenside_b, ep_file, ep_rank, halfmove, fullmove


def _is_on_board(r: int, c: int) -> bool:
    return 0 <= r < 8 and 0 <= c < 8


def _piece_type(piece: str) -> str:
    return piece.upper()


def _is_piece(piece: str) -> bool:
    return piece in PIECE_CHARS


def _is_white(piece: str) -> bool:
    return piece.isupper()


def _is_black(piece: str) -> bool:
    return piece.islower()


def _king_pos(board, side):
    king_char = 'K' if side == 'w' else 'k'
    for r in range(8):
        for c in range(8):
            if board[r][c] == king_char:
                return r, c
    return None


def _algebraic(r: int, c: int) -> str:
    """Convert board (row, col) 0-indexed to algebraic notation.
    row 0 = rank 1, row 7 = rank 8, col 0 = file a, col 7 = file h."""
    return f"{chr(ord('a') + c)}{r + 1}"


def _is_square_attacked(board, r, c, side):
    """Check if square (r, c) is attacked by the given side."""
    opponent = 'b' if side == 'w' else 'w'
    for i in range(8):
        for j in range(8):
            piece = board[i][j]
            if not _is_piece(piece) or _is_white(piece) != (side == 'w'):
                continue
            ptype = _piece_type(piece)
