                        if not _is_piece(target):
                            moves.append(f"{_algebraic(r, c)}{_algebraic(nr, nc)}")
                        elif _is_white(target) != _is_white(piece):
                            moves.append(f"{_algebraic(r, c)}{_algebraic(nr, nc)}")
                            break
                        else:
                            break

            elif ptype == 'K':
                # Regular king moves (one square in any direction)
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if _is_on_board(nr, nc):
                            target = board[nr][nc]
                            if not _is_piece(target) or _is_white(target) != _is_white(piece):
                                moves.append(f"{_algebraic(r, c)}{_algebraic(nr, nc)}")

    # Castling (after pawn moves)
    # Determine king row based on side
    if side == 'w':
        king_row = kr
    else:
        king_row = kr

    # Kingside castling (O-O)
    if side == 'w' and castle_kingside_w:
        # White kingside: path f1(g1 must be empty, cols 5,6)
        path_clear = board[king_row][5] == '--' and board[king_row][6] == '--'
        if path_clear:
            if not _is_square_attacked(board, king_row, 5, 'b') and \
               not _is_square_attacked(board, king_row, 6, 'b'):
                moves.append(f"e1g1")

    if side == 'w' and castle_queenside_w:
        # White queenside: path d1,c1,b1 must be empty (cols 1,2,3)
        path_clear = True
        for fc in range(1, 4):
            if board[king_row][fc] != '--':
                path_clear = False
                break
        if path_clear:
            if not _is_square_attacked(board, king_row, 3, 'b') and \
               not _is_square_attacked(board, king_row, 2, 'b'):
                moves.append(f"e1c1")

    if side == 'b' and castle_kingside_b:
        # Black kingside: path f8,g8 (cols 5,6)
        path_clear = True
        for fc in range(5, 7):
            if board[king_row][fc] != '--':
                path_clear = False
                break
        if path_clear:
            if not _is_square_attacked(board, king_row, 5, 'w') and \
               not _is_square_attacked(board, king_row, 6, 'w'):
                moves.append(f"e8g8")

    if side == 'b' and castle_queenside_b:
        # Black queenside: path d8,c8,b8 (cols 1,2,3)
        path_clear = True
        for fc in range(1, 4):
            if board[king_row][fc] != '--':
                path_clear = False
                break
        if path_clear:
            if not _is_square_attacked(board, king_row, 3, 'w') and \
               not _is_square_attacked(board, king_row, 2, 'w'):
                moves.append(f"e8c8")

    # Return all pseudo-legal moves (prompt says don't worry about check legality)
    return moves


def _make_move(board, move: str):
    """Apply a move to the board. Returns new board (doesn't mutate original).
    Move format: UCI like 'e2e4' or 'e7e8q'."""
    if len(move) == 4:
        from_sq = move[:2]
        to_sq = move[2:]
        promo = None
    elif len(move) == 5:
        from_sq = move[:2]
        to_sq = move[2:4]
        promo = move[4]
    else:
        return board

    from_file = ord(from_sq[0]) - ord('a')
    from_rank = int(from_sq[1]) - 1
    to_file = ord(to_sq[0]) - ord('a')
    to_rank = int(to_sq[1]) - 1

    new_board = [row[:] for row in board]
    piece = new_board[from_rank][from_file]
    new_board[to_rank][to_file] = piece
    new_board[from_rank][from_file] = '--'

    # Pawn promotion
    if piece == 'wP' and to_rank == 7:
        new_board[to_rank][to_file] = promo if promo else 'wQ'
    elif piece == 'bP' and to_rank == 0:
        new_board[to_rank][to_file] = promo if promo else 'bQ'

    return new_board


def _board_to_fen(board, side, fullmove=1, castle_kingside_w=True, castle_queenside_w=True,
                  castle_kingside_b=True, castle_queenside_b=True):
    """Convert board to FEN string (simplified, no en passant)."""
    board_str = ''
    for r in range(7, -1, -1):
        empty = 0
        for c in range(8):
            if board[r][c] == '--':
                empty += 1
            else:
                if empty > 0:
                    board_str += str(empty)
                    empty = 0
                board_str += board[r][c]
        if empty > 0:
            board_str += str(empty)
        if r > 0:
            board_str += '/'

    # Castling rights
    castling = ''
    if castle_kingside_w:
        castling += 'K'
    if castle_queenside_w:
        castling += 'Q'
    if castle_kingside_b:
        castling += 'k'
    if castle_queenside_b:
        castling += 'q'
    if not castling:
        castling = '-'

    return f"{board_str} {side} {castling} - 0 {fullmove}"


def perft(fen: str, depth: int) -> int:
    """Perft: return number of leaf nodes at given depth.
    perft(0) == 1. Counts pseudo-legal moves at each node.
    """

    if depth == 0:
        return 1

    board, side, _, _, _, _, _, _, _, _ = _parse_fen(fen)
    moves = legal_moves(fen)

    if not moves:
        return 1

    total = 0
    for move in moves:
        new_board = _make_move(board, move)
        new_side = 'b' if side == 'w' else 'w'
        new_fen = _board_to_fen(new_board, new_side, fullmove=1,
                                 castle_kingside_w=True, castle_queenside_w=True,
                                 castle_kingside_b=True, castle_queenside_b=True)
        total += perft(new_fen, depth - 1)

    return total
